<?php
use App\Domain\Statistics\StatisticViewData; use App\Models\{Statistic,User}; use Illuminate\Foundation\Testing\RefreshDatabase; uses(RefreshDatabase::class); beforeEach(function(){file_put_contents(storage_path('app/installed'),now()->toIso8601String());App\Models\WebsiteSetting::query()->create(['site_name'=>'Test','site_url'=>'https://example.test','timezone'=>'UTC']);}); afterEach(fn()=>@unlink(storage_path('app/installed'))); test('statistic preserves the exact configured display value',function(){$item=Statistic::factory()->published()->create(['label'=>'Verified metric','value'=>'001.50','prefix'=>'~','suffix'=>' units']);$data=app(StatisticViewData::class)->published();expect($data[0]['displayed_value'])->toBe('~001.50 units');}); test('statistic validation enforces factual shape',function(){$user=User::factory()->create(['is_active'=>true]);$this->actingAs($user)->post('/content/statistics',['label'=>'','value'=>'','statistic_group'=>'analytics','source_url'=>'https://user:pass@example.com'])->assertSessionHasErrors(['label','value','statistic_group','source_url']);}); test('statistics do not have a standalone public route',function(){expect(Route::has('statistics.index'))->toBeFalse();}); test('statistics admin is protected',function(){$this->get('/content/statistics')->assertRedirect('/login');});
